runtimeTemplate:
/* --- ANTIGRAVITY CHINESE LOCALIZATION START --- */
try {
(() => {
    {{GUARD}}

    let translatedCount = 0;
    const map = new Map({{MAP_JSON}});
    const lowerMap = new Map();
    for (const [k, v] of map.entries()) lowerMap.set(k.toLowerCase(), v);

    const longEntries = {{LONG_JSON}};
    const translatedValues = new WeakMap();
    const SKIP_TAGS = ['SCRIPT', 'STYLE', 'PRE', 'CODE', 'TEXTAREA', 'SVG'];

    try {
        if (!window.__origConfirm) {
            window.__origConfirm = window.confirm;
            window.confirm = function(msg) {
                if (typeof msg === 'string') {
                    if (/^Are you sure you want to delete the hook "(.+?)"\?$/i.test(msg)) {
                        msg = msg.replace(/^Are you sure you want to delete the hook "(.+?)"\?$/i, '您确定要删除 Hook “$1” 吗？');
                    } else if (msg === 'Are you sure you want to delete this handler?') {
                        msg = '您确定要删除此处理程序吗？';
                    } else if (msg === 'Are you sure you want to delete this hook card?') {
                        msg = '您确定要删除此 Hook 卡片吗？';
                    }
                }
                return window.__origConfirm.call(window, msg);
            };
        }
    } catch(e) {}

    function isProtectedArea(node) {
        try {
            if (!node) return false;
            const el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
            if (!el || typeof el.closest !== 'function') return false;
            return !!el.closest('.monaco-editor, [contenteditable="true"], pre, code, textarea, .xterm, [role="article"], [data-markdown-root], .agy-user-bubble');
        } catch (e) {
            return false;
        }
    }

    function isCodeOrEditor(node) {
        return isProtectedArea(node);
    }

    function norm(s) {
        if (!s) return '';
        return s.replace(/\s+/g, ' ').replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/…/g, '...').trim();
    }

    function translateWithShortcut(val) {
        if (!val) return null;
        const match = val.match(/^(.+?)\s*\((Ctrl|Cmd|Alt|Shift|⌘|⌥|⇧|⌃)\+?([^)]*)\)$/i);
        if (match) {
            const prefix = match[1].trim();
            const normPref = norm(prefix);
            const lowerPref = normPref.toLowerCase();
            let transPref = null;
            if (map.has(normPref)) transPref = map.get(normPref);
            else if (lowerMap.has(lowerPref)) transPref = lowerMap.get(lowerPref);
            if (transPref) return transPref + " (" + match[2] + (match[3] ? "+" + match[3] : "") + ")";
        }
        return null;
    }

    function translateDynamicString(valNorm) {
        if (!valNorm) return null;

        // 1. 耗时与思考时长
        if (/^Worked for (\d+)m (\d+)s$/i.test(valNorm)) {
            return valNorm.replace(/^Worked for (\d+)m (\d+)s$/i, '耗时 $1 分钟 $2 秒');
        } else if (/^Worked for (\d+)h (\d+)m$/i.test(valNorm)) {
            return valNorm.replace(/^Worked for (\d+)h (\d+)m$/i, '耗时 $1 小时 $2 分钟');
        } else if (/^Worked for (\d+)h$/i.test(valNorm)) {
            return valNorm.replace(/^Worked for (\d+)h$/i, '耗时 $1 小时');
        } else if (/^Worked for (\d+)m$/i.test(valNorm)) {
            return valNorm.replace(/^Worked for (\d+)m$/i, '耗时 $1 分钟');
        } else if (/^Worked for (\d+)s$/i.test(valNorm)) {
            return valNorm.replace(/^Worked for (\d+)s$/i, '耗时 $1 秒');
        } else if (/^Thought for (\d+)m (\d+)s$/i.test(valNorm)) {
            return valNorm.replace(/^Thought for (\d+)m (\d+)s$/i, '思考了 $1 分钟 $2 秒');
        } else if (/^Thought for (\d+)h (\d+)m$/i.test(valNorm)) {
            return valNorm.replace(/^Thought for (\d+)h (\d+)m$/i, '思考了 $1 小时 $2 分钟');
        } else if (/^Thought for (\d+)h$/i.test(valNorm)) {
            return valNorm.replace(/^Thought for (\d+)h$/i, '思考了 $1 小时');
        } else if (/^Thought for (\d+)m$/i.test(valNorm)) {
            return valNorm.replace(/^Thought for (\d+)m$/i, '思考了 $1 分钟');
        } else if (/^Thought for (\d+)s$/i.test(valNorm)) {
            return valNorm.replace(/^Thought for (\d+)s$/i, '思考了 $1 秒');

        // 2. 步骤状态与动作前缀
        } else if (/^Explored\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Explored\s+(\d+)\s+files?(.*)$/i, '已检索 $1 个文件$2');
        } else if (/^Exploring\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Exploring\s+(\d+)\s+files?(.*)$/i, '正在检索 $1 个文件$2');
        } else if (/^Explore\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Explore\s+(\d+)\s+files?(.*)$/i, '检索 $1 个文件$2');
        } else if (/^Ran\s+(\d+)\s+commands?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Ran\s+(\d+)\s+commands?(.*)$/i, '已运行 $1 个命令$2');
        } else if (/^Running\s+(\d+)\s+commands?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Running\s+(\d+)\s+commands?(.*)$/i, '运行中 $1 个命令$2');
        } else if (/^Run\s+(\d+)\s+commands?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Run\s+(\d+)\s+commands?(.*)$/i, '运行 $1 个命令$2');
        } else if (/^Edited\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Edited\s+(\d+)\s+files?(.*)$/i, '已编辑 $1 个文件$2');
        } else if (/^Editing\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Editing\s+(\d+)\s+files?(.*)$/i, '正在编辑 $1 个文件$2');
        } else if (/^Edit\s+(\d+)\s+files?(.*)$/i.test(valNorm)) {
            return valNorm.replace(/^Edit\s+(\d+)\s+files?(.*)$/i, '编辑 $1 个文件$2');
        } else if (/^(\d+)\s+files?,\s*(\d+)\s+folders?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+files?,\s*(\d+)\s+folders?$/i, '$1 个文件，$2 个文件夹');
        } else if (/^(\d+)\s+folders?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+folders?$/i, '$1 个文件夹');
        } else if (/^(\d+)\s+commands?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+commands?$/i, '$1 个命令');
        } else if (/^(\d+)\s+files?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+files?$/i, '$1 个文件');
        } else if (/^(\d+)\s+tasks?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+tasks?$/i, '$1 个任务');
        } else if (/^(\d+)\s+steps?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+steps?$/i, '$1 个步骤');
        } else if (/^(\d+)\s+tools?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+tools?$/i, '$1 个工具');
        } else if (/^(\d+)\s+changes?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+changes?$/i, '$1 处更改');
        } else if (/^(\d+)\s+items?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+items?$/i, '$1 个项目');
        } else if (/^(\d+)\s+agents?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+agents?$/i, '$1 个智能体');
        } else if (/^(\d+)\s+subagents?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+subagents?$/i, '$1 个子代理');
        } else if (/^(\d+)\s+lines?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+lines?$/i, '$1 行');
        } else if (/^(\d+)\s+insertions?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+insertions?$/i, '$1 处新增');
        } else if (/^(\d+)\s+deletions?$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+deletions?$/i, '$1 处删除');

        // 3. 单个操作动词
        } else if (/^Explored$/i.test(valNorm)) {
            return '已检索';
        } else if (/^Exploring$/i.test(valNorm)) {
            return '正在检索';
        } else if (/^Explore$/i.test(valNorm)) {
            return '检索';
        } else if (/^Ran$/i.test(valNorm)) {
            return '已运行';
        } else if (/^Running$/i.test(valNorm)) {
            return '运行中';
        } else if (/^Run$/i.test(valNorm)) {
            return '运行';
        } else if (/^Edited$/i.test(valNorm)) {
            return '已编辑';
        } else if (/^Editing$/i.test(valNorm)) {
            return '正在编辑';
        } else if (/^Edit$/i.test(valNorm)) {
            return '编辑';
        } else if (/^Working\.\.\.$/i.test(valNorm)) {
            return '正在处理...';
        } else if (/^Thinking\.\.\.$/i.test(valNorm)) {
            return '思考中...';
        } else if (/^Ran\s+command:\s*\x60(.+)\x60$/i.test(valNorm)) {
            return valNorm.replace(/^Ran\s+command:\s*\x60(.+)\x60$/i, '运行命令: `$1`');
        } else if (/^Ran\s+command$/i.test(valNorm)) {
            return '已运行命令';
        } else if (/^Running\s+command$/i.test(valNorm)) {
            return '正在运行命令';
        } else if (/^Run\s+command$/i.test(valNorm)) {
            return '运行命令';
        } else if (/^Run\s+(.+)\s+finished$/i.test(valNorm)) {
            return valNorm.replace(/^Run\s+(.+)\s+finished$/i, '运行 $1 已完成');
        } else if (/^Run\s+(.+)\s+failed$/i.test(valNorm)) {
            return valNorm.replace(/^Run\s+(.+)\s+failed$/i, '运行 $1 失败');
        } else if (/^Ran\s+(.+)\s+finished$/i.test(valNorm)) {
            return valNorm.replace(/^Ran\s+(.+)\s+finished$/i, '已运行 $1 完成');
        } else if (/^Ran\s+(.+)\s+failed$/i.test(valNorm)) {
            return valNorm.replace(/^Ran\s+(.+)\s+failed$/i, '已运行 $1 失败');

        // 4. Built-in Skills 标题匹配（截图 2 重点）
        } else if (valNorm === 'agy-customizations') {
            return '自定义系统 (agy-customizations)';
        } else if (valNorm === 'generative_ui') {
            return '动态 UI 生成 (generative_ui)';
        } else if (valNorm === 'migrate-workflows') {
            return '工作流迁移 (migrate-workflows)';
        } else if (valNorm === 'permissioned-github') {
            return 'GitHub 权限交互 (permissioned-github)';
        } else if (valNorm === 'antigravity-guide') {
            return '官方指南';

        // 4.1 斜杠快捷命令描述动态匹配
        } else if (/^Compact the conversation now/i.test(valNorm)) {
            return '立即压缩会话（总结历史上下文以释放上下文窗口空间）。';
        } else if (/^Run until the specified goal is completely finished\.?$/i.test(valNorm)) {
            return '持续自主运行，直至指定的目标完全完成。';
        } else if (/^Run an instruction on a recurring schedule or as a one-time timer\.?$/i.test(valNorm)) {
            return '按循环周期或作为一次性定时器自动运行指令。';
        } else if (/^Invoke a browser agent for web tasks\.?$/i.test(valNorm)) {
            return '调用浏览器智能体执行网页浏览与自动化任务。';
        } else if (/^Plan carefully before executing a task\.?$/i.test(valNorm)) {
            return '在执行复杂任务前，进行严密的分步规划。';
        } else if (/^Interview me to align on a plan\.?$/i.test(valNorm)) {
            return '通过互动访谈与我深度对齐方案设计。';
        } else if (/^Invoke a team of agents to autonomously tackle large projects\.?$/i.test(valNorm)) {
            return '调用多智能体团队自主协作攻坚大型项目。';
        } else if (/^Reflect on recent successes or corrections to capture reusable skills or rules\.?$/i.test(valNorm)) {
            return '反思近期成功经验或纠错记录，总结提炼为可复用的 Skill 或规则。';
        } else if (/^Invoke the Boost multi-agent orchestrator for complex tasks\.?$/i.test(valNorm)) {
            return '调用 Boost 深度思考多智能体编排器处理复杂任务。';
        } else if (/^Ask a quick question without interrupting the main conversation\.?$/i.test(valNorm)) {
            return '在不打断主会话流程的情况下快速提问。';

        // 5. Built-in Skills 描述匹配（前缀截断与省略号全兼容）
        } else if (valNorm.startsWith('Comprehensive guide and reference for the Antigravity Customization System') || valNorm.startsWith('Comprehensive guide and reference')) {
            return 'Antigravity 自定义系统的综合指南与参考手册。用于解释自定义配置的工作原理、加载优先级、发现机制，并指导 Skills、Rules、Plugins、Hooks 和 MCP 服务器的创建。';
        } else if (valNorm.startsWith('How to render rich interactive HTML widgets inline in the chat') || valNorm.startsWith('How to render rich interactive HTML widgets')) {
            return '如何在对话中内嵌渲染丰富的交互式 HTML 小部件或独立交付件。当您希望向用户展示图表、数据可视化、交互控件、教学演练或任何丰富视觉内容时使用此 Skill。';
        } else if (valNorm.startsWith('Automatically migrate legacy workflows to modern skills across global') || valNorm.startsWith('Automatically migrate legacy workflows')) {
            return '在全局和工作区配置中，自动将旧版工作流迁移为现代 Skills。扫描现有工作流，创建目标 SKILL.md 文件，并安全归档旧的工作流文件。';
        } else if (valNorm.startsWith('Guidelines for interacting with GitHub and request permissions') || valNorm.startsWith('Guidelines for interacting with GitHub')) {
            return '与 GitHub 交互的准则规范，并在智能体环境中因限制导致命令失败时向用户请求相应权限。';
        } else if (valNorm.startsWith('Provides a comprehensive guide, quick reference, and sitemap for Google Antigravity') || valNorm.startsWith('Provides a comprehensive guide')) {
            return '提供 Google Antigravity (AGY) 的综合指南、快速参考与全景导航，涵盖 Antigravity 命令行 (agy CLI)、Antigravity 2.0、IDE、Python SDK、斜杠命令、快捷键以及自定义配置（Skill、规则、MCP、Sidecars 插件等）。';

        // 6. 智能体设置与权限面板（截图 1 重点）
        } else if (/^Controls the actions the agent can take\.?$/i.test(valNorm)) {
            return '控制智能体可以执行的操作。';
        } else if (/^Modify permissions for file, terminal, and MCP tools\.?$/i.test(valNorm)) {
            return '修改文件、终端和 MCP 工具的权限。';
        } else if (/^Tool Permissions(?:\s*(\d+))?$/i.test(valNorm)) {
            return valNorm.replace(/^Tool Permissions(?:\s*(\d+))?$/i, (m, num) => num ? '工具权限 ' + num : '工具权限');
        } else if (/^Tool Permissions$/i.test(valNorm)) {
            return '工具权限';
        } else if (/^Whether the agent asks you to review its documents\.?$/i.test(valNorm)) {
            return '智能体是否要求您审查其文档。';
        } else if (/^to be installed\.?$/i.test(valNorm)) {
            return '需要先安装。';
        } else if (/^There are no customizations enabled\.?$/i.test(valNorm)) {
            return '暂无已启用的自定义配置。';
        } else if (/^技能预设\s*(\d*)$/.test(valNorm)) {
            return valNorm.replace(/^技能预设/, 'Skills 预设');
        } else if (valNorm.includes('技能、规则、MCP')) {
            return valNorm.replace(/技能、规则、MCP/g, 'Skills、规则、MCP');

        // 7. 模型选择列表与思考强度（截图 3 重点）
        } else if (/^Select model,\s*current:\s*(.+)$/i.test(valNorm)) {
            return valNorm.replace(/^Select model,\s*current:\s*(.+)$/i, (m, cur) => '选择模型，当前: ' + cur);

        // 8. 预设与链接说明
        } else if (/^Learn more about$/i.test(valNorm)) {
            return '了解更多关于';
        } else if (/^Learn more about\s+(.+)$/i.test(valNorm)) {
            return valNorm.replace(/^Learn more about\s+(.+)$/i, (m, p) => {
                let translatedPreset = p;
                if (/^default/i.test(p)) translatedPreset = "默认预设 (Default)";
                else if (/^full machine/i.test(p)) translatedPreset = "全机访问 (Full Machine)";
                else if (/^turbo/i.test(p)) translatedPreset = "极速模式 (Turbo)";
                else if (/^custom/i.test(p)) translatedPreset = "自定义 (Custom)";
                return "了解更多关于 " + translatedPreset;
            });
        } else if (/^Yes, and always allow '(.+)' in this project$/i.test(valNorm)) {
            return valNorm.replace(/^Yes, and always allow '(.+)' in this project$/i, (m, cmd) => "是，且在此项目中始终允许运行 '" + cmd + "'");
        } else if (/^Yes, and always allow '(.+)'$/i.test(valNorm)) {
            return valNorm.replace(/^Yes, and always allow '(.+)'$/i, (m, cmd) => "是，且始终允许运行 '" + cmd + "'");
        } else if (/^(\d+) tools? enabled$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+) tools? enabled$/i, (m, num) => num + " 个工具已启用");
        } else if (/^Show\s+(\d+)\s+more/i.test(valNorm)) {
            return valNorm.replace(/^Show\s+(\d+)\s+more(\s+(results?|items?|commands?|options?))?(\.\.\.|…)?$/i, (m, num, p2, type) => {
                if (type) {
                    if (/result/i.test(type)) return "显示另外 " + num + " 个结果...";
                    if (/command/i.test(type)) return "显示另外 " + num + " 个命令...";
                    if (/item/i.test(type)) return "显示另外 " + num + " 个项目...";
                    if (/option/i.test(type)) return "显示另外 " + num + " 个选项...";
                }
                return "显示另外 " + num + " 个...";
            });
        } else if (/^See all\s*\((\d+)\)$/i.test(valNorm)) {
            return valNorm.replace(/^See all\s*\((\d+)\)$/i, (m, num) => "显示全部 (" + num + ")");
        } else if (/^Available AI Credits: (\d+)$/i.test(valNorm)) {
            return valNorm.replace(/^Available AI Credits: (\d+)$/i, (m, num) => "可用 AI 额度: " + num);
        } else if (/^Version\s+([\d\.]+)$/i.test(valNorm)) {
            return valNorm.replace(/^Version\s+([\d\.]+)$/i, (m, v) => "版本 " + v);
        } else if (/^(\d+)(s|m|h|d|w|mo|yr|y)(?:\s+ago)?$/i.test(valNorm) && (/ago$/i.test(valNorm) || /^\d+(?:[smhdwy]|mo|yr)$/.test(valNorm))) {
            return valNorm.replace(/^(\d+)(s|m|h|d|w|mo|yr|y)(?:\s+ago)?$/i, (m, num, unit) => {
                const unitLower = unit.toLowerCase();
                let unitStr = "";
                if (unitLower === "s") unitStr = "秒前";
                else if (unitLower === "m") unitStr = "分钟前";
                else if (unitLower === "h") unitStr = "小时前";
                else if (unitLower === "d") unitStr = "天前";
                else if (unitLower === "w") unitStr = "周前";
                else if (unitLower === "mo") unitStr = "个月前";
                else if (unitLower === "yr" || unitLower === "y") unitStr = "年前";
                return num + unitStr;
            });
        } else if (/^(\d+)\s+files?\s+changed$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+files?\s+changed$/i, '$1 处文件更改');
        } else if (/^Load older messages,\s*showing\s*(\d+)\s*of\s*(\d+)$/i.test(valNorm)) {
            return valNorm.replace(/^Load older messages,\s*showing\s*(\d+)\s*of\s*(\d+)$/i, '加载更早的消息，正在显示 $1 / $2');
        } else if (/^No more older messages,\s*showing\s*(\d+)\s*of\s*(\d+)$/i.test(valNorm)) {
            return valNorm.replace(/^No more older messages,\s*showing\s*(\d+)\s*of\s*(\d+)$/i, '没有更早的消息了，正在显示 $1 / $2');
        } else if (/^No more older messages$/i.test(valNorm)) {
            return '没有更早的消息了';
        } else if (/^Expand message$/i.test(valNorm)) {
            return '展开消息';
        } else if (/^Collapse message$/i.test(valNorm)) {
            return '折叠消息';
        } else if (/^Show\s+(\d+)\s+breakdowns?$/i.test(valNorm)) {
            return valNorm.replace(/^Show\s+(\d+)\s+breakdowns?$/i, '显示 $1 项明细');
        } else if (/^Skills:\s*(\d+)\s*tokens$/i.test(valNorm)) {
            return valNorm.replace(/^Skills:\s*(\d+)\s*tokens$/i, 'Skills: $1 Tokens');
        } else if (/^No agents running$/i.test(valNorm)) {
            return '暂无运行中的智能体';
        } else if (/^(\d+)\s+agents?\s+running$/i.test(valNorm)) {
            return valNorm.replace(/^(\d+)\s+agents?\s+running$/i, '$1 个智能体运行中');
        } else if (/^Setting up WSL:\s*(.+)$/i.test(valNorm)) {
            return valNorm.replace(/^Setting up WSL:\s*(.+)$/i, '正在配置 WSL: $1');
        } else if (/^Installing into\s*(.+)…$/i.test(valNorm)) {
            return valNorm.replace(/^Installing into\s*(.+)…$/i, '正在安装至 $1…');
        } else if (/^Agent permissions preset selector,\s*current:\s*(.+)$/i.test(valNorm)) {
            return valNorm.replace(/^Agent permissions preset selector,\s*current:\s*(.+)$/i, (m, cur) => {
                let transCur = cur;
                if (/^turbo/i.test(cur)) transCur = '极速模式 (Turbo)';
                else if (/^default/i.test(cur)) transCur = '默认预设 (Default)';
                else if (/^full machine/i.test(cur)) transCur = '全机访问 (Full Machine)';
                else if (/^custom/i.test(cur)) transCur = '自定义 (Custom)';
