    function translateSlashCommands(root) {
        try {
            if (!root) return;
            const isOption = root.getAttribute && (root.getAttribute('role') === 'option' || (root.id && root.id.startsWith('typeahead-item-')));
            const options = isOption ? [root] : (root.querySelectorAll ? root.querySelectorAll('[role="option"], [id^="typeahead-item-"]') : []);
            if (!options || options.length === 0) return;
            for (const opt of options) {
                const nameEl = opt.querySelector('.text-xs.shrink-0');
                if (nameEl) {
                    const rawName = nameEl.textContent.trim();
                    if (!rawName.includes('(')) {
                        if (slashNames[rawName] && nameEl.textContent !== slashNames[rawName]) {
                            nameEl.textContent = slashNames[rawName];
                            translatedCount++;
                        }
                    }
                }
                const descEl = opt.querySelector('.text-xs.opacity-50');
                if (descEl) {
                    const rawDesc = descEl.textContent.trim().replace(/\.$/, '');
                    if (slashDescs[rawDesc]) {
                        if (descEl.textContent !== slashDescs[rawDesc]) {
                            descEl.textContent = slashDescs[rawDesc];
                            translatedCount++;
                        }
                    } else {
                        for (const [k, v] of Object.entries(slashDescs)) {
                            if (rawDesc.startsWith(k)) {
                                if (descEl.textContent !== v) {
                                    descEl.textContent = v;
                                    translatedCount++;
                                }
                                break;
                            }
                        }
                    }
                }
            }
        } catch(e) {}
    }

    function isLeafTextContainer(el) {
        if (!el || !el.childNodes || el.childNodes.length === 0) return false;
        for (let i = 0; i < el.childNodes.length; i++) {
            const c = el.childNodes[i];
            if (c.nodeType === 1 && ['P', 'DIV', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'UL', 'OL', 'LI', 'SECTION', 'ARTICLE', 'MAIN', 'NAV', 'HEADER', 'FOOTER'].includes(c.tagName)) {
                return false;
            }
        }
        return true;
    }

    function translateElementFragments(el) {
        if (!isLeafTextContainer(el)) return false;
        const text = norm(el.textContent);
        if (!text) return false;

        // 1. "No <noun> yet" (例如: No 自动化 yet, No automations yet, No scheduled tasks yet, 暂无自动化 yet, No 自动化)
