        if (/^No\s+(.+?)\s+yet\.?$/i.test(text)) {
            isNoYet = true;
            noun = text.match(/^No\s+(.+?)\s+yet\.?$/i)[1].trim();
        } else if (/^暂无\s*(.+?)\s+yet\.?$/i.test(text)) {
            isNoYet = true;
            noun = text.match(/^暂无\s*(.+?)\s+yet\.?$/i)[1].trim();
        } else if (/^No\s+(.+?)$/i.test(text) && (
            (el.closest && el.closest('[data-testid="sidecar-list-empty"]')) ||
            (el.getAttribute && el.getAttribute('data-testid') === 'sidecar-list-empty') ||
            /^(automations?|scheduled tasks?|tasks?|coordinators?|swarms?|自动化|定时任务|任务|协调员)$/i.test(text.match(/^No\s+(.+?)$/i)[1].trim())
        )) {
            isNoYet = true;
            noun = text.match(/^No\s+(.+?)$/i)[1].trim();
        }

        if (isNoYet) {
            if (map.has(noun)) noun = map.get(noun);
            else if (lowerMap.has(noun.toLowerCase())) noun = lowerMap.get(noun.toLowerCase());
            if (el.childNodes.length === 1 && el.childNodes[0].nodeType === 3) {
                el.childNodes[0].nodeValue = '暂无' + noun;
                translatedValues.set(el.childNodes[0], '暂无' + noun);
            } else if (el.childNodes.length >= 2) {
                if (el.childNodes[0] && el.childNodes[0].nodeType === 3) {
                    el.childNodes[0].nodeValue = '暂无';
                    translatedValues.set(el.childNodes[0], '暂无');
                }
                if (el.childNodes[1] && el.childNodes[1].nodeType === 3) {
